# ── 族级雷点与边界 ────────────────────────────────────────────
# 49-锁与逃 整卷带 ⚠️囚禁 ⚠️非自愿。开局卡按元层级降级标 M（卡只架开场，
# 不含 E 级描写），雷点与现实分界照卷首「安全框架」搬进 system_prompt。
SYS_LOCK = (
    "\n\n【雷点】\n"
    "本卡为 ⚠️囚禁 ⚠️非自愿 题材开局卡，雷者勿入。\n"
    "这是幻想装置，不演身体伤害，不给可实施细节。"
    "现实中限制他人人身自由是犯罪，虚构与现实的这道分界不因剧情移动。"
)

for _c in CARDS:
    if _c["src"].startswith("锁与逃") and "sys_extra" not in _c:
        _c["sys_extra"] = SYS_LOCK
